.surefeedback-dashboard-react {
  padding: 20px 0;
  background: #f9fafb;
  min-height: 100vh;
}

.dashboard-header {
  margin-bottom: 32px;
}

.dashboard-title {
  font-size: 24px;
  font-weight: 600;
  color: #111827;
  margin: 0 0 8px 0;
}

.dashboard-subtitle {
  font-size: 14px;
  color: #6b7280;
  margin: 0;
}

.dashboard-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 24px;
  max-width: 1200px;
}

.dashboard-card {
  background: #ffffff;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  box-shadow: 0 1px 3px 0 rgba(0, 0, 0, 0.1), 0 1px 2px 0 rgba(0, 0, 0, 0.06);
  overflow: hidden;
  transition: all 0.3s ease;
}

.dashboard-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 12px 0 rgba(0, 0, 0, 0.1), 0 2px 4px 0 rgba(0, 0, 0, 0.06);
}

.card-header {
  background: #f9fafb;
  border-bottom: 1px solid #e5e7eb;
  padding: 16px 20px;
}

.card-title {
  font-size: 16px;
  font-weight: 600;
  color: #111827;
  margin: 0;
}

.card-content {
  padding: 20px;
}

/* Connection Status Styles */
.status-connected,
.status-disconnected {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 20px;
}

.status-icon-wrapper {
  flex-shrink: 0;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.status-connected .status-icon-wrapper {
  background: #d1fae5;
}

.status-disconnected .status-icon-wrapper {
  background: #fef3c7;
}

.status-icon {
  width: 20px;
  height: 20px;
}

.status-icon.success {
  color: #059669;
}

.status-icon.warning {
  color: #d97706;
}

.status-content {
  flex: 1;
}

.status-title {
  font-size: 14px;
  font-weight: 600;
  color: #111827;
  margin: 0 0 4px 0;
}

.status-description {
  font-size: 13px;
  color: #6b7280;
  margin: 0;
}

.connection-details {
  background: #f9fafb;
  border: 1px solid #e5e7eb;
  border-radius: 6px;
  padding: 16px;
  margin-bottom: 20px;
}

.detail-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 0;
}

.detail-item:not(:last-child) {
  border-bottom: 1px solid #e5e7eb;
}

.detail-label {
  font-size: 13px;
  font-weight: 500;
  color: #374151;
}

.detail-value {
  font-size: 13px;
  color: #6b7280;
  font-family: 'Figtree', sans-serif;
}

/* Button Styles */
.card-actions {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  border-radius: 6px;
  font-size: 13px;
  font-weight: 500;
  text-decoration: none;
  transition: all 0.2s ease;
  border: 1px solid transparent;
}

.btn-primary {
  background: #1d4ed8;
  color: #ffffff;
  border-color: #1d4ed8;
}

.btn-primary:hover {
  background: #1e40af;
  border-color: #1e40af;
  transform: translateY(-1px);
  color: #ffffff;
  text-decoration: none;
}

.btn-secondary {
  background: #f9fafb;
  color: #374151;
  border-color: #d1d5db;
}

.btn-secondary:hover {
  background: #f3f4f6;
  border-color: #9ca3af;
  transform: translateY(-1px);
  color: #374151;
  text-decoration: none;
}

.btn-icon {
  width: 16px;
  height: 16px;
}

/* Stats Grid */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.stat-item {
  text-align: center;
}

.stat-number {
  display: block;
  font-size: 20px;
  font-weight: 700;
  color: #1d4ed8;
  margin-bottom: 4px;
}

.stat-label {
  display: block;
  font-size: 11px;
  color: #6b7280;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  font-weight: 500;
}

/* Help & Documentation */
.help-description {
  font-size: 14px;
  color: #6b7280;
  margin: 0 0 16px 0;
}

.help-links {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.help-link {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  background: #f9fafb;
  border: 1px solid #e5e7eb;
  border-radius: 6px;
  color: #374151;
  text-decoration: none;
  transition: all 0.2s ease;
}

.help-link:hover {
  background: #f3f4f6;
  border-color: #1d4ed8;
  color: #1d4ed8;
  text-decoration: none;
}

.help-icon {
  width: 18px;
  height: 18px;
  color: #6b7280;
}

.help-link:hover .help-icon {
  color: #1d4ed8;
}

/* Responsive Design */
@media (max-width: 1024px) {
  .dashboard-grid {
    grid-template-columns: 1fr;
    gap: 20px;
  }
}

@media (max-width: 768px) {
  .surefeedback-dashboard-react {
    padding: 16px 0;
  }
  
  .dashboard-grid {
    gap: 16px;
  }
  
  .card-content {
    padding: 16px;
  }
  
  .stats-grid {
    grid-template-columns: 1fr;
    gap: 16px;
  }
  
  .card-actions {
    flex-direction: column;
  }
  
  .btn {
    justify-content: center;
  }
